import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";import{_ as i}from"./chunks/assets.DMkeNHu3.js";var a=JSON.parse(`{"title":"Attachment - Managing Attachments","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/attachment.md","filePath":"03-developer/models/attachment.md"}`),o={name:`03-developer/models/attachment.md`};function s(n,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[e(`<h1 id="attachment-managing-attachments" tabindex="-1">Attachment - Managing Attachments <a class="header-anchor" href="#attachment-managing-attachments" aria-label="Permalink to “Attachment - Managing Attachments”">​</a></h1><p><img src="`+i+`" alt="attachment.webp" width="1853" height="799"></p><p>The Attachment section is used to upload and manage files intended to be displayed in site content, made available for users to download, or attached to different parts of the site, such as posts and products.</p><p>On this page, you can enter file information, specify how it should be displayed on the site, and, if needed, assign it to a specific section of the site.</p><h2 id="_1-tips-page-guide" tabindex="-1">1. Tips - Page guide <a class="header-anchor" href="#_1-tips-page-guide" aria-label="Permalink to “1. Tips - Page guide”">​</a></h2><p>Tips on using attachments are displayed at the top of the sidebar:</p><ul><li>If you do not want the file to appear in the site&#39;s public attachment list and it is only used for attaching to other sections, disable <strong>Is fillable</strong>.</li><li>Premium files are intended for customers to download after payment. These files should not be made available to all users like regular files.</li></ul><h2 id="_2-title-slug-and-subtitle-attachment-information" tabindex="-1">2. Title, Slug, and Subtitle - Attachment information <a class="header-anchor" href="#_2-title-slug-and-subtitle-attachment-information" aria-label="Permalink to “2. Title, Slug, and Subtitle - Attachment information”">​</a></h2><h3 id="title" tabindex="-1">Title <a class="header-anchor" href="#title" aria-label="Permalink to “Title”">​</a></h3><p>Enter the file title. This title helps you identify the attachment in the admin panel and is used in sections where the file name is displayed.</p><p>For example: <code>News manifest</code></p><h3 id="slug" tabindex="-1">Slug <a class="header-anchor" href="#slug" aria-label="Permalink to “Slug”">​</a></h3><p>The attachment&#39;s text identifier, used to create its URL. This value is usually generated from the file title.</p><p>For example: <code>news-manifest</code></p><p>Changing this value may also change the attachment URL, so it is best not to change it unnecessarily after publication.</p><h3 id="subtitle" tabindex="-1">Subtitle <a class="header-anchor" href="#subtitle" aria-label="Permalink to “Subtitle”">​</a></h3><p>Enter a brief description of the file here. The subtitle can provide the user with additional information about the title.</p><p>For example, if the attachment is a training file, you can enter its subject or version here.</p><h2 id="_3-description-attachment-description" tabindex="-1">3. Description - Attachment description <a class="header-anchor" href="#_3-description-attachment-description" aria-label="Permalink to “3. Description - Attachment description”">​</a></h2><p>You can enter a more detailed description of the file here. The text editor lets you format content and use common text-editing features.</p><p>Use this section to describe the file&#39;s content, introduce its purpose, or provide instructions for downloading and using it.</p><h2 id="_4-file-uploading-and-downloading-the-file" tabindex="-1">4. File - Uploading and downloading the file <a class="header-anchor" href="#_4-file-uploading-and-downloading-the-file" aria-label="Permalink to “4. File - Uploading and downloading the file”">​</a></h2><p>Upload the attachment&#39;s main file here. After uploading, information such as the file name, extension, and size is displayed.</p><h3 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to “Download”">​</a></h3><p>The Download button lets you download the uploaded file from the admin panel. Use it to download the file and check its integrity or contents.</p><h3 id="short-code" tabindex="-1">Short Code <a class="header-anchor" href="#short-code" aria-label="Permalink to “Short Code”">​</a></h3><p>After the file is saved, a unique code labeled Short Code is displayed; for example:</p><p><code>[ATTACHED:2]</code></p><p>You can copy this code and use it in a post&#39;s content or in a supported text section.</p><p>When the content is displayed on the site, the code is replaced with output appropriate to the file type:</p><ul><li><strong>Image:</strong> The image itself is displayed.</li><li><strong>Audio file:</strong> An audio player is displayed so the user can play the file.</li><li><strong>Video:</strong> A video player is displayed.</li><li><strong>Other files:</strong> A download link for the file is displayed.</li></ul><p>For example, to place an audio file within an article, simply enter its Short Code at the desired location in the content.</p><p>This method lets you place a file in site content without manually entering code to display an image, player, or download link.</p><h2 id="_5-is-fillable-display-in-the-public-list" tabindex="-1">5. Is fillable - Display in the public list <a class="header-anchor" href="#_5-is-fillable-display-in-the-public-list" aria-label="Permalink to “5. Is fillable - Display in the public list”">​</a></h2><p>This option specifies whether the attachment is displayed in the site&#39;s public attachment list.</p><ul><li><strong>Enabled:</strong> The attachment can be displayed in the site&#39;s public attachment list.</li><li><strong>Disabled:</strong> The attachment is kept for use in other parts of the site without needing to appear in the public attachment list.</li></ul><p>For example, if you uploaded a file only to use within an article and do not want it to appear separately in the attachment list, disable this option.</p><p>Disabling this option does not, by itself, restrict direct access to the file; this setting controls whether it appears in the public list.</p><h2 id="_6-is-premium-premium-attachment" tabindex="-1">6. Is premium - Premium attachment <a class="header-anchor" href="#_6-is-premium-premium-attachment" aria-label="Permalink to “6. Is premium - Premium attachment”">​</a></h2><p>This option is for files that require purchase or special access to download.</p><p>For example, you can designate a training file, exclusive catalog, or downloadable document as a premium attachment so that it is intended for customers after payment.</p><ul><li><strong>Enabled:</strong> The attachment is designated as a premium file.</li><li><strong>Disabled:</strong> The attachment is treated as a regular file.</li></ul><p>Note that enabling this option does not, by itself, manage purchases or download permissions; actual access to the file must be controlled by the site&#39;s purchase and permission mechanisms.</p><h2 id="_7-attaching-attaching-an-attachment-to-site-sections" tabindex="-1">7. Attaching - Attaching an attachment to site sections <a class="header-anchor" href="#_7-attaching-attaching-an-attachment-to-site-sections" aria-label="Permalink to “7. Attaching - Attaching an attachment to site sections”">​</a></h2><p>Use this section to attach the file to a specific entity on the site, such as a post, product, or gallery.</p><p>This feature is useful when you want the file to be recognized as an attachment to a specific section, rather than simply exist as a standalone file on the site.</p><h3 id="group" tabindex="-1">Group <a class="header-anchor" href="#group" aria-label="Permalink to “Group”">​</a></h3><p>This section displays the section or entity related to the attachment. Depending on the type of attachment, you may first need to select the desired destination.</p><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to “Search”">​</a></h3><p>Use the search field to find the entity you want to attach the file to.</p><p>For example, if you want to attach a PDF file to a post, search for and select the desired post.</p><p>Attachments can be connected to sections such as:</p><ul><li>Products</li><li>Posts</li><li>Groups</li><li>Categories</li><li>Clips</li><li>Galleries</li><li>Creators</li></ul><p>After selecting the destination and saving the changes, the file will be associated with the selected entity.</p><p><strong>Note:</strong> Attaching a file to a post or product differs from inserting its Short Code into the content. Attaching establishes a relationship between the file and that entity; the Short Code is used to place the file&#39;s output at a specific location in the content.</p><h2 id="_8-saving-changes" tabindex="-1">8. Saving changes <a class="header-anchor" href="#_8-saving-changes" aria-label="Permalink to “8. Saving changes”">​</a></h2><p>After entering the information, uploading the file, and configuring the required options, click the Save button to record the changes.</p><p>Before saving, check that the title and description are correct, the intended file has been uploaded, and the options for public display, premium status, and attachment to site sections are configured as needed.</p><h2 id="pre-save-checklist" tabindex="-1">Pre-save checklist <a class="header-anchor" href="#pre-save-checklist" aria-label="Permalink to “Pre-save checklist”">​</a></h2><ul><li>The file title and subtitle have been entered.</li><li>Any necessary file description has been added.</li><li>The correct file has been uploaded.</li><li>If the file needs to be used in site content, its Short Code is available.</li><li>Its display status in the public list has been specified.</li><li>If needed, the file&#39;s premium status has been configured.</li><li>If the file belongs to a post, product, or another section, the attachment destination has been selected.</li><li>The changes have been saved.</li></ul>`,60)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};